<script setup>
import {ref,reactive,onMounted,onUnmounted,watch} from 'vue';import {native,api,on,state} from './native.js';import Icon from './Icon.vue';import AppSelect from './AppSelect.vue';import AppOverlay from './AppOverlay.vue';
const engine=ref({phase:'idle',installed:false,riskAccepted:false}),servers=ref([]),error=ref(''),busy=ref(''),showRisk=ref(false),advanced=ref(false);
let saved={};try{saved=JSON.parse(localStorage.getItem('hxz-mobile-game')||'{}');}catch{}
const options=reactive({memoryMB:[0,1024,2048,3072,4096,6144].includes(saved.memoryMB)?saved.memoryMB:0,renderer:['auto','nggl4es','virgl','zink'].includes(saved.renderer)?saved.renderer:'auto',autoUpdate:saved.autoUpdate!==false,autoJoin:saved.autoJoin!==false});
watch(options,v=>localStorage.setItem('hxz-mobile-game',JSON.stringify(v)));const unsubscribe=on('gameEngine',v=>engine.value=v);
async function refresh(){try{const [e,s]=await Promise.all([native('gameEngine'),api('/api/server-presets')]);engine.value=e;servers.value=s.servers;}catch(e){error.value=e.message;}}
async function action(name,values={}){error.value='';if(!engine.value.riskAccepted&&!['accept','state','cancel'].includes(name)){showRisk.value=true;return;}busy.value=values.id||name;try{const r=await native('gameEngine',{action:name,...values});if(name!=='launch')engine.value=r;}catch(e){error.value=e.message;}finally{busy.value='';}}
async function accept(){await action('accept',{accepted:true});showRisk.value=false;}
const size=v=>(Math.max(0,v||0)/1024/1024).toFixed(1)+' MB';
onMounted(refresh);onUnmounted(unsubscribe);
</script>
<template><section class="content-page mobile-minecraft">
  <header class="page-toolbar"><h1>Minecraft</h1><button class="icon-button" aria-label="刷新游戏配置" @click="refresh"><Icon name="refresh"/></button></header>
  <p v-if="error" class="inline-error" role="alert">{{error}}</p>
  <section class="card engine-status"><div class="engine-heading"><span class="discover-icon"><Icon name="games"/></span><div><h2>游戏运行组件</h2><p>{{engine.installed?'已安装 '+engine.version:engine.message}}</p></div></div>
    <template v-if="engine.busy"><progress :value="engine.received||0" :max="engine.total||1"/><p>{{size(engine.received)}} / {{size(engine.total)}}</p><button class="soft-button" @click="action('cancel')">暂停下载</button></template>
    <div v-else class="actions"><button v-if="!engine.installed" class="primary" @click="action(engine.ready?'install':'download')"><Icon name="download"/>{{engine.ready?'安装组件':'下载运行组件'}}</button><button v-else class="soft-button" @click="action('settings')"><Icon name="settings"/>触控与高级设置</button><button v-if="engine.installed" class="soft-button" @click="action(engine.ready?'install':'download')">{{engine.ready?'安装组件更新':'检查组件更新'}}</button><button class="soft-button" @click="showRisk=true">运行提示</button></div>
    <p v-if="engine.phase==='error'||engine.phase==='paused'" class="inline-error">{{engine.message}}</p>
  </section>
  <article v-for="(server,index) in servers" :key="server.id" class="card mobile-server-card"><div class="engine-heading"><span class="server-number">0{{index+1}}</span><div><h2>{{server.name}}</h2><p>{{server.profileSource==='hxzup'?'随服务器整合包更新':server.version+' · '+(server.loader||'原版')}}</p></div></div><p v-if="!server.enabled" class="muted">服务器当前未开放</p><p v-else-if="server.updateRequired" class="muted">管理员要求启动前完成更新</p><div class="actions"><button class="primary" :disabled="!state.hasAccount||!server.enabled||!!busy||engine.busy" @click="engine.installed?action('launch',{id:server.id,options:{...options}}):action('download')"><Icon name="play"/>{{busy===server.id?'正在准备':engine.installed?'安装并进入':'准备游戏环境'}}</button><button class="soft-button" :disabled="!engine.installed||!state.hasAccount||!server.enabled||!!busy" @click="action('launch',{id:server.id,options:{...options,prepareOnly:true}})">仅安装</button></div></article>
  <p v-if="!state.hasAccount" class="card muted">请在「我的」登录幻想镇皮肤站后进入服务器。</p>
  <section class="card mobile-runtime-settings"><button class="engine-settings-trigger" :aria-expanded="advanced" @click="advanced=!advanced"><h2>运行设置</h2><Icon :name="advanced?'close':'settings'"/></button><div v-if="advanced" class="runtime-options"><label>内存分配<AppSelect v-model="options.memoryMB" label="游戏内存" :options="[{value:0,label:'自动分配'},... [1024,2048,3072,4096,6144].map(v=>({value:v,label:(v/1024)+' GB'}))]"/></label><label>渲染器<AppSelect v-model="options.renderer" label="渲染器" :options="[{value:'auto',label:'跟随运行引擎'},{value:'nggl4es',label:'NG-GL4ES · 优先兼容'},{value:'virgl',label:'VirGL · 图形兼容'},{value:'zink',label:'Zink · 需要 Vulkan 支持'}]"/></label><label class="engine-switch"><span>启动前更新整合包</span><input v-model="options.autoUpdate" type="checkbox"></label><label class="engine-switch"><span>启动后自动进入服务器</span><input v-model="options.autoJoin" type="checkbox"></label></div></section>
  <AppOverlay :open="showRisk" label="手机游戏运行提示" kind="confirm" @close="showRisk=false"><section class="sheet engine-risk-dialog"><header class="sheet-header"><h2>先了解手机运行条件</h2><button class="icon-button" aria-label="关闭" @click="showRisk=false"><Icon name="close"/></button></header><div class="sheet-body engine-risk-body"><p>这是独立的 ARM64 Java 游戏运行组件，基于 FCL 开源运行环境。社区和语音继续留在幻想镇社区中。</p><ul><li>电脑模组不保证支持手机，大型整合包可能无法启动。</li><li>安装会下载数 GB 内容；建议连接 Wi-Fi，预留存储和内存。</li><li>游戏可能发热、耗电或被系统回收。提高内存不一定更快。</li><li>皮肤站登录令牌仅传给同签名的本地组件，不写入启动请求文件。</li><li>游戏存档在运行组件中；卸载组件前请先备份。</li></ul><button class="primary" @click="accept">了解并启用</button></div></section></AppOverlay>
</section></template>
<style scoped>
.mobile-minecraft{gap:16px}.engine-status,.mobile-server-card,.mobile-runtime-settings{display:grid;gap:16px}.engine-heading{display:flex;gap:14px;align-items:center;min-width:0}.engine-heading>div{min-width:0}.engine-heading h2,.engine-heading p{margin:0}.engine-heading p{margin-top:5px;color:var(--muted);overflow-wrap:anywhere}.server-number{font-weight:700;font-variant-numeric:tabular-nums;font-size:24px;opacity:.5;width:44px;flex-shrink:0}.mobile-minecraft .actions{flex-wrap:wrap;gap:10px}.mobile-minecraft .actions button{flex:1 1 auto;min-height:44px}.engine-settings-trigger{display:flex;align-items:center;justify-content:space-between;background:none;border:0;padding:0;color:inherit;text-align:left;min-height:44px}.engine-settings-trigger h2{margin:0}.runtime-options{display:grid;gap:18px}.runtime-options>label{display:grid;gap:8px;min-width:0}.runtime-options .engine-switch{display:flex;gap:16px;justify-content:space-between;align-items:center}.engine-switch input{width:22px;height:22px;flex:none}.mobile-minecraft progress{width:100%}.engine-risk-dialog{border-radius:24px;overflow:hidden}.engine-risk-body{display:grid;gap:16px}.engine-risk-body ul{margin:0;padding-left:20px;line-height:1.65}.engine-risk-body li+li{margin-top:10px}
</style>
